window.TTS_DATA=window.TTS_DATA||{};window.TTS_DATA[3]=[{"t": "h", "l": 0, "s": "Лекц 3. Трансформатор, автотрансформаторын орлуулах схем ба параметр", "h": "<b>Лекц 3. Трансформатор, автотрансформаторын</b> <b>орлуулах схем ба параметр</b>"}, {"t": "p", "s": "Багш: Тэнхимийн эрхлэгч, доктор (Ph.D), дэд профессор Ш.Гантөмөр · Хугацаа: 2 цаг", "h": "Багш: Тэнхимийн эрхлэгч, доктор (Ph.D), дэд профессор Ш.Гантөмөр · Хугацаа: 2 цаг"}, {"t": "p", "s": "Лекцийн зорилго. Хоёр ба гурван ороомогт трансформатор, автотрансформаторын орлуулах схемийг байгуулж, паспортын өгөгдлөөс Rт, Xт, Gт, Bт-г тооцох; трансформаторын чадлын алдагдал, хүчдэлийн уналтыг тодорхойлох; хувиргалтын коэффициентыг (РПН) тооцоонд оруулах хамгийн тохиромжтой трансформатортой П схем, түүний матриц хэлбэрийг эзэмших.", "h": "<b>Лекцийн зорилго. </b>Хоёр ба гурван ороомогт трансформатор, автотрансформаторын орлуулах схемийг байгуулж, паспортын өгөгдлөөс R<sub>т</sub>, X<sub>т</sub>, G<sub>т</sub>, B<sub>т</sub>-г тооцох; трансформаторын чадлын алдагдал, хүчдэлийн уналтыг тодорхойлох; хувиргалтын коэффициентыг (РПН) тооцоонд оруулах хамгийн тохиромжтой трансформатортой П схем, түүний матриц хэлбэрийг эзэмших.", "x": "obj"}, {"t": "p", "s": "Түлхүүр үг: хоосон явалт, богино залгааны туршилт, uк%, Г схем, гурван ороомогт трансформатор, автотрансформатор, хувиргалтын коэффициент, РПН, ПБВ, хамгийн тохиромжтой трансформатор.", "h": "<b>Түлхүүр үг: </b>хоосон явалт, богино залгааны туршилт, u<sub>к</sub>%, Г схем, гурван ороомогт трансформатор, автотрансформатор, хувиргалтын коэффициент, РПН, ПБВ, хамгийн тохиромжтой трансформатор.", "x": "obj"}, {"t": "h", "l": 1, "s": "1. Трансформаторын үүрэг ба төрөл", "h": "<b>1. Трансформаторын үүрэг ба төрөл</b>"}, {"t": "p", "s": "Хүчний трансформатор нь цахилгаан эрчим хүчийг нэг хүчдэлийн түвшингээс нөгөөд хувиргах үндсэн элемент юм. Генераторын гаралтын (6.3–20 кВ) хүчдэлийг дамжуулах (110–220 кВ) хүчдэл болгон өсгөх, түгээх ба хэрэглэгчийн хүчдэл болгон бууруулах трансформатор нь цахилгаан системийн суурилагдсан чадлын 6–8 дахин их нийт чадалтай байдаг — эрчим хүч хэрэглэгчид хүрэх хүртэл 3–5 удаа хувирдаг. Иймд трансформаторын алдагдал сүлжээний нийт алдагдлын 30–40 %-ийг эзэлдэг.", "h": "Хүчний трансформатор нь цахилгаан эрчим хүчийг нэг хүчдэлийн түвшингээс нөгөөд хувиргах үндсэн элемент юм. Генераторын гаралтын (6.3–20 кВ) хүчдэлийг дамжуулах (110–220 кВ) хүчдэл болгон <b>өсгөх</b>, түгээх ба хэрэглэгчийн хүчдэл болгон <b>бууруулах </b>трансформатор нь цахилгаан системийн суурилагдсан чадлын 6–8 дахин их нийт чадалтай байдаг — эрчим хүч хэрэглэгчид хүрэх хүртэл 3–5 удаа хувирдаг. Иймд трансформаторын алдагдал сүлжээний нийт алдагдлын 30–40 %-ийг эзэлдэг."}, {"t": "p", "s": "Трансформаторыг дараах шинжээр ангилна:", "h": "Трансформаторыг дараах шинжээр ангилна:"}, {"t": "p", "s": "Ороомгийн тоо: хоёр ороомогт (ТД, ТДН, ТРДН), гурван ороомогт (ТДТН), хуваагдмал ороомогтой (ТРДН — нам талд хоёр ороомог);", "h": "<b>Ороомгийн тоо: </b>хоёр ороомогт (ТД, ТДН, ТРДН), гурван ороомогт (ТДТН), хуваагдмал ороомогтой (ТРДН — нам талд хоёр ороомог);"}, {"t": "p", "s": "Автотрансформатор (АТДЦТН) — дээд ба дунд хүчдэлийн ороомог цахилгаанаар холбогдсон;", "h": "<b>Автотрансформатор </b>(АТДЦТН) — дээд ба дунд хүчдэлийн ороомог цахилгаанаар холбогдсон;"}, {"t": "p", "s": "Хүчдэл тохируулах арга: ачаалал дор тохируулах РПН (тэмдэглэгээнд «Н»), ачаалалгүй үед шилжүүлэх ПБВ;", "h": "<b>Хүчдэл тохируулах арга: </b>ачаалал дор тохируулах РПН (тэмдэглэгээнд «Н»), ачаалалгүй үед шилжүүлэх ПБВ;"}, {"t": "p", "s": "Хөргөлт: М (тосон, байгалийн), Д (тос + үлээгч), ДЦ (тосны албадмал эргэлт), Ц (тос-ус).", "h": "<b>Хөргөлт: </b>М (тосон, байгалийн), Д (тос + үлээгч), ДЦ (тосны албадмал эргэлт), Ц (тос-ус)."}, {"t": "p", "s": "Жишээ нь ТДН-16000/110 нь гурван фазын, тос-үлээгчээр хөргөдөг, ачаалал дор хүчдэл тохируулдаг, 16 000 кВА чадалтай, дээд хүчдэл 110 кВ ангиллын трансформатор юм.", "h": "Жишээ нь ТДН-16000/110 нь гурван фазын, тос-үлээгчээр хөргөдөг, ачаалал дор хүчдэл тохируулдаг, 16 000 кВА чадалтай, дээд хүчдэл 110 кВ ангиллын трансформатор юм."}, {"t": "h", "l": 1, "s": "2. Паспортын өгөгдөл ба туршилт", "h": "<b>2. Паспортын өгөгдөл ба туршилт</b>"}, {"t": "p", "s": "Трансформаторын орлуулах схемийн параметрийг үйлдвэрийн хоёр туршилтын үр дүнгээр (паспортын өгөгдлөөр) тодорхойлно.", "h": "Трансформаторын орлуулах схемийн параметрийг үйлдвэрийн хоёр туршилтын үр дүнгээр (паспортын өгөгдлөөр) тодорхойлно."}, {"t": "p", "s": "Хоосон явалтын туршилт. Нэг ороомогт нэрлэсэн хүчдэл өгч, нөгөөг задгай үлдээнэ. Хэмжсэн чадал нь соронзон цөмийн алдагдал (гистерезис, эргүүлэг гүйдэл) ΔPх, гүйдэл нь соронзлох гүйдэл Iх% (нэрлэсэн гүйдлийн хувиар). Хоосон явалтын алдагдал хүчдэлийн квадраттай пропорциональ, ачааллаас хамаардаггүй — тогтмол алдагдал.", "h": "<b>Хоосон явалтын туршилт. </b>Нэг ороомогт нэрлэсэн хүчдэл өгч, нөгөөг задгай үлдээнэ. Хэмжсэн чадал нь соронзон цөмийн алдагдал (гистерезис, эргүүлэг гүйдэл) ΔP<sub>х</sub>, гүйдэл нь соронзлох гүйдэл I<sub>х</sub>% (нэрлэсэн гүйдлийн хувиар). Хоосон явалтын алдагдал хүчдэлийн квадраттай пропорциональ, ачааллаас хамаардаггүй — <b>тогтмол алдагдал</b>."}, {"t": "p", "s": "Богино залгааны туршилт. Нэг ороомгийг богино залгаж, нөгөөд нэрлэсэн гүйдэл гүйх хүртэл хүчдэлийг өсгөнө. Энэ хүчдэлийн нэрлэсэн хүчдэлд харьцуулсан хувийг богино залгааны хүчдэл uк%, хэмжсэн чадлыг ороомгийн (зэс) алдагдал ΔPк гэнэ. Ороомгийн алдагдал гүйдлийн квадраттай пропорциональ — хувьсах алдагдал.", "h": "<b>Богино залгааны туршилт. </b>Нэг ороомгийг богино залгаж, нөгөөд нэрлэсэн гүйдэл гүйх хүртэл хүчдэлийг өсгөнө. Энэ хүчдэлийн нэрлэсэн хүчдэлд харьцуулсан хувийг <b>богино залгааны хүчдэл </b>u<sub>к</sub>%, хэмжсэн чадлыг ороомгийн (зэс) алдагдал ΔP<sub>к</sub> гэнэ. Ороомгийн алдагдал гүйдлийн квадраттай пропорциональ — <b>хувьсах алдагдал</b>."}, {"t": "tbl", "s": "", "head": ["Трансформатор", "S , МВА н", "U /U , кВ вн нн", "u , % к", "ΔP , кВт к", "ΔP , кВт х", "I , % х"], "rows": [["ТМН-6300/35", "6.3", "35/11", "7.5", "46.5", "9.2", "0.9"], ["ТДН-10000/110", "10", "115/11", "10.5", "60", "14", "0.7"], ["ТДН-16000/110", "16", "115/11", "10.5", "85", "19", "0.7"], ["ТРДН-25000/110", "25", "115/10.5", "10.5", "120", "27", "0.7"], ["ТРДН-40000/110", "40", "115/10.5", "10.5", "172", "36", "0.65"], ["ТРДЦН-63000/220", "63", "230/11", "12", "300", "82", "0.8"]]}, {"t": "cap", "s": "Хүснэгт 3.1. Хоёр ороомогт трансформаторын паспортын ойролцоо өгөгдөл", "h": "Хүснэгт 3.1. Хоёр ороомогт трансформаторын паспортын ойролцоо өгөгдөл"}, {"t": "h", "l": 1, "s": "3. Хоёр ороомогт трансформаторын орлуулах схем", "h": "<b>3. Хоёр ороомогт трансформаторын орлуулах схем</b>"}, {"t": "p", "s": "Трансформаторыг Т хэлбэрийн орлуулах схемээр төлөөлж, соронзлох салааг дээд хүчдэлийн үзүүрт шилжүүлбэл Г хэлбэрийн схем гарна: цуваа Zт = Rт + jXт (хоёр ороомгийн эсэргүүцэл, бүгдийг нэг хүчдэлд шилжүүлсэн) ба хөндлөн Yт = Gт − jBт (соронзлох салаа). Хөндлөн дамжууламж индуктив тул хасах тэмдэгтэй — шугамын багтаамжаас ялгаатай нь идэвхгүй чадал хэрэглэнэ.", "h": "Трансформаторыг Т хэлбэрийн орлуулах схемээр төлөөлж, соронзлох салааг дээд хүчдэлийн үзүүрт шилжүүлбэл <b>Г хэлбэрийн </b>схем гарна: цуваа Z<sub>т</sub> = R<sub>т</sub> + jX<sub>т</sub> (хоёр ороомгийн эсэргүүцэл, бүгдийг нэг хүчдэлд шилжүүлсэн) ба хөндлөн Y<sub>т</sub> = G<sub>т</sub> − jB<sub>т</sub> (соронзлох салаа). Хөндлөн дамжууламж индуктив тул хасах тэмдэгтэй — шугамын багтаамжаас ялгаатай нь идэвхгүй чадал <b>хэрэглэнэ</b>."}, {"t": "p", "s": "1 Rт + jXт 2", "h": "<sub>1</sub> R<sub>т</sub> <sub>+</sub> <sub>jXт</sub> <sub>2</sub>"}, {"t": "p", "s": "Gт − jBт хатмргаинйснф.тоkхиромжтой", "h": "G<sub>т</sub> <sub>−</sub> <sub>jBт</sub> <sub>хатмргаинйснф.тоkхиромжтой</sub>"}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 634}, {"t": "cap", "s": "Зураг 3.1. Хоёр ороомогт трансформаторын Г хэлбэрийн орлуулах схем", "h": "Зураг 3.1. Хоёр ороомогт трансформаторын Г хэлбэрийн орлуулах схем"}, {"t": "p", "s": "Паспортын өгөгдлөөс параметрийг тооцох томьёо (Uн — параметрийг шилжүүлэх талын нэрлэсэн хүчдэл, кВ; Sн — МВА; ΔP — МВт):", "h": "Паспортын өгөгдлөөс параметрийг тооцох томьёо (U<sub>н</sub> — параметрийг шилжүүлэх талын нэрлэсэн хүчдэл, кВ; S<sub>н</sub> — МВА; ΔP — МВт):"}, {"t": "eq", "s": "Rт = ΔPк·Uн²/Sн² ; Xт = uк%·Uн²/(100·Sн) (3.1)", "h": "R<sub>т</sub> = ΔP<sub>к</sub>·U<sub>н</sub>²/S<sub>н</sub>² ; X<sub>т</sub> = u<sub>к</sub>%·U<sub>н</sub>²/(100·S<sub>н</sub>) (3.1)", "n": "3.1", "img": "data:image/png;base64,", "iw": 478}, {"t": "eq", "s": "Gт = ΔPх/Uн² ; Bт = Iх%·Sн/(100·Uн²) (3.2)", "h": "G<sub>т</sub> = ΔP<sub>х</sub>/U<sub>н</sub>² ; B<sub>т</sub> = I<sub>х</sub>%·S<sub>н</sub>/(100·U<sub>н</sub>²) (3.2)", "n": "3.2", "img": "data:image/png;base64,", "iw": 466}, {"t": "p", "s": "Томьёо (3.1)-д uк% нь бүрэн эсэргүүцлийн хувь боловч том трансформаторт Rт ≪ Xт (X/R = 15–40) тул Xт ≈ Zт гэж үзнэ. Нарийвчилбал Xт = √(Zт² − Rт²).", "h": "Томьёо (3.1)-д u<sub>к</sub>% нь бүрэн эсэргүүцлийн хувь боловч том трансформаторт R<sub>т</sub> ≪ X<sub>т</sub> (X/R = 15–40) тул X<sub>т</sub> ≈ Z<sub>т</sub> гэж үзнэ. Нарийвчилбал X<sub>т</sub> = √(Z<sub>т</sub>² − R<sub>т</sub>²)."}, {"t": "p", "s": "Тогтсон горимын гар тооцоонд соронзлох салааг ихэвчлэн тогтмол ачаалал болгон орлуулдаг:", "h": "Тогтсон горимын гар тооцоонд соронзлох салааг ихэвчлэн <b>тогтмол ачаалал </b>болгон орлуулдаг:"}, {"t": "eq", "s": "ΔṠх = ΔPх + jΔQх ; ΔQх = Iх%·Sн/100 (3.3)", "h": "ΔṠ<sub>х</sub> = ΔP<sub>х</sub> + jΔQ<sub>х</sub> ; ΔQ<sub>х</sub> = I<sub>х</sub>%·S<sub>н</sub>/100 (3.3)", "n": "3.3", "img": "data:image/png;base64,", "iw": 463}, {"t": "p", "s": "Жишээ 3.1. ТДН-16000/110 (хүснэгт 3.1) трансформаторын параметрийг 115 кВ талд шилжүүлж тооцоолно уу.", "h": "<b>Жишээ 3.1. </b>ТДН-16000/110 (хүснэгт 3.1) трансформаторын параметрийг 115 кВ талд шилжүүлж тооцоолно уу.", "x": "ex"}, {"t": "p", "s": "Rт = 0.085·115²/16² = 0.085·13 225/256 = 4.39 Ом; Xт = 10.5·13 225/(100·16) = 86.8 Ом; Gт = 0.019/13 225 = 1.44·10⁻⁶ См; Bт = 0.7·16/(100·13 225) = 8.47·10⁻⁶ См;", "h": "R<sub>т</sub> = 0.085·115²/16² = 0.085·13 225/256 = 4.39 Ом; X<sub>т</sub> = 10.5·13 225/(100·16) = 86.8 Ом; G<sub>т</sub> = 0.019/13 225 = 1.44·10⁻⁶ См; B<sub>т</sub> = 0.7·16/(100·13 225) = 8.47·10⁻⁶ См;", "x": "ex"}, {"t": "p", "s": "ΔṠх = 0.019 + j0.112 МВА. X/R = 19.8.", "h": "ΔṠ<sub>х</sub> = 0.019 + j0.112 МВА. X/R = 19.8.", "x": "ex"}, {"t": "p", "s": "Харьцуулбал: 100 км 110 кВ шугамын X ≈ 41 Ом (лекц 2) — 16 МВА трансформаторын хуурмаг эсэргүүцэл 200 км шугамтай тэнцэх тул сүлжээний хүчдэлийн уналтын дийлэнх хэсэг трансформаторт ногддог.", "h": "Харьцуулбал: 100 км 110 кВ шугамын X ≈ 41 Ом (лекц 2) — 16 МВА трансформаторын хуурмаг эсэргүүцэл 200 км шугамтай тэнцэх тул сүлжээний хүчдэлийн уналтын дийлэнх хэсэг трансформаторт ногддог.", "x": "ex"}, {"t": "h", "l": 1, "s": "4. Трансформаторын чадлын алдагдал ба хүчдэлийн уналт", "h": "<b>4. Трансформаторын чадлын алдагдал ба хүчдэлийн уналт</b>"}, {"t": "p", "s": "Ачаалал S үеийн трансформаторын алдагдал:", "h": "Ачаалал S үеийн трансформаторын алдагдал:"}, {"t": "eq", "s": "ΔPт = ΔPх + ΔPк·(S/Sн)² ; ΔQт = Iх%·Sн/100 + uк%·Sн/100·(S/Sн)² (3.4)", "h": "ΔP<sub>т</sub> = ΔP<sub>х</sub> + ΔP<sub>к</sub>·(S/S<sub>н</sub>)² ; ΔQ<sub>т</sub> = I<sub>х</sub>%·S<sub>н</sub>/100 + u<sub>к</sub>%·S<sub>н</sub>/100·(S/S<sub>н</sub>)² (3.4)", "n": "3.4", "img": "data:image/png;base64,", "iw": 557}, {"t": "p", "s": "S/Sн = β-г ачааллын коэффициент гэнэ. n ижил трансформатор зэрэгцээ ажиллавал:", "h": "S/S<sub>н</sub> = β-г <b>ачааллын коэффициент </b>гэнэ. n ижил трансформатор зэрэгцээ ажиллавал:"}, {"t": "eq", "s": "ΔP = n·ΔPх + ΔPк·(S/Sн)²/n (3.5)", "h": "ΔP = n·ΔP<sub>х</sub> + ΔP<sub>к</sub>·(S/S<sub>н</sub>)²/n (3.5)", "n": "3.5", "img": "data:image/png;base64,", "iw": 428}, {"t": "p", "s": "Хүчдэлийн уналтыг шугамынхтай ижил томьёогоор (лекц 1, 1.4) Rт, Xт-ээр тооцно. Ашигт үйлийн коэффициент η = P/(P + ΔPт) нь ΔPх = ΔPкβ² үед (тогтмол ба хувьсах алдагдал тэнцэх) хамгийн их байна: βопт = √(ΔPх/ΔPк), ТДН-16000-д √(19/85) = 0.47.", "h": "Хүчдэлийн уналтыг шугамынхтай ижил томьёогоор (лекц 1, 1.4) R<sub>т</sub>, X<sub>т</sub>-ээр тооцно. Ашигт үйлийн коэффициент η = P/(P + ΔP<sub>т</sub>) нь ΔP<sub>х</sub> = ΔP<sub>к</sub>β² үед (тогтмол ба хувьсах алдагдал тэнцэх) хамгийн их байна: β<sub>опт</sub> = √(ΔP<sub>х</sub>/ΔP<sub>к</sub>), ТДН-16000-д √(19/85) = 0.47."}, {"t": "p", "s": "Жишээ 3.2. ТДН-16000/110 нам талын ачаалал Ṡ = 12 + j8 МВА, дээд талын хүчдэл 115 кВ. Алдагдал, хүчдэлийн уналт, нам талын хүчдэлийг олно уу (нэрлэсэн салбар, k = 115/11).", "h": "<b>Жишээ 3.2. </b>ТДН-16000/110 нам талын ачаалал Ṡ = 12 + j8 МВА, дээд талын хүчдэл 115 кВ. Алдагдал, хүчдэлийн уналт, нам талын хүчдэлийг олно уу (нэрлэсэн салбар, k = 115/11).", "x": "ex"}, {"t": "p", "s": "S = 14.42 МВА; β² = (14.42/16)² = 0.8125.", "h": "S = 14.42 МВА; β² = (14.42/16)² = 0.8125.", "x": "ex"}, {"t": "p", "s": "ΔPт = 19 + 85·0.8125 = 19 + 69.1 = 88.1 кВт; ΔQт = 0.112 + 0.105·16·0.8125 = 0.112 + 1.365 = 1.477 Мвар.", "h": "ΔP<sub>т</sub> = 19 + 85·0.8125 = 19 + 69.1 = 88.1 кВт; ΔQ<sub>т</sub> = 0.112 + 0.105·16·0.8125 = 0.112 + 1.365 = 1.477 Мвар.", "x": "ex"}, {"t": "p", "s": "Хүчдэлийн уналт (ойролцоогоор дээд хүчдэлээр): ΔU = (12·4.39 + 8·86.8)/115 = (52.7 + 694.4)/115 = 6.50 кВ; δU = (12·86.8 − 8·4.39)/115 = 8.75 кВ.", "h": "Хүчдэлийн уналт (ойролцоогоор дээд хүчдэлээр): ΔU = (12·4.39 + 8·86.8)/115 = (52.7 + 694.4)/115 = 6.50 кВ; δU = (12·86.8 − 8·4.39)/115 = 8.75 кВ.", "x": "ex"}, {"t": "p", "s": "Дээд хүчдэлд шилжүүлсэн нам талын хүчдэл: U′2 = √[(115 − 6.50)² + 8.75²] ≈ 108.9 кВ; нам талд U2 = 108.9·11/115 = 10.41 кВ. Идэвхгүй чадлын алдагдал 1.48 Мвар нь ачааллын", "h": "Дээд хүчдэлд шилжүүлсэн нам талын хүчдэл: U′<sub>2</sub> = √[(115 − 6.50)² + 8.75²] ≈ 108.9 кВ; нам талд U<sub>2</sub> = 108.9·11/115 = 10.41 кВ. Идэвхгүй чадлын алдагдал 1.48 Мвар нь ачааллын", "x": "ex"}, {"t": "p", "s": "Q-ийн 18 % — трансформатор идэвхгүй чадлын томоохон хэрэглэгч.", "h": "Q-ийн 18 % — трансформатор идэвхгүй чадлын томоохон хэрэглэгч.", "x": "ex"}, {"t": "h", "l": 1, "s": "5. Гурван ороомогт трансформатор", "h": "<b>5. Гурван ороомогт трансформатор</b>"}, {"t": "p", "s": "Гурван ороомогт трансформатор (дээд — В, дунд — С, нам — Н) нь гурван хүчдэлийн сүлжээг холбоно. Орлуулах схем нь од хэлбэрийн гурван цацраг (ZВ, ZС, ZН) ба соронзлох салаа. Паспортад хос ороомгийн хоорондох uк% өгөгдөнө: uкВС, uкВН, uкСН. Цацраг бүрийн утга:", "h": "Гурван ороомогт трансформатор (дээд — В, дунд — С, нам — Н) нь гурван хүчдэлийн сүлжээг холбоно. Орлуулах схем нь <b>од хэлбэрийн </b>гурван цацраг (Z<sub>В</sub>, Z<sub>С</sub>, Z<sub>Н</sub>) ба соронзлох салаа. Паспортад хос ороомгийн хоорондох u<sub>к</sub>% өгөгдөнө: u<sub>кВС</sub>, u<sub>кВН</sub>, u<sub>кСН</sub>. Цацраг бүрийн утга:"}, {"t": "p", "s": "uкВ = ½(uкВС + uкВН − uкСН) ; uкС = ½(uкВС + uкСН − uкВН) ; uкН = ½(uкВН +", "h": "u<sub>кВ</sub> = ½(u<sub>кВС</sub> + u<sub>кВН</sub> − u<sub>кСН</sub>) ; u<sub>кС</sub> = ½(u<sub>кВС</sub> + u<sub>кСН</sub> − u<sub>кВН</sub>) ; u<sub>кН</sub> = ½(u<sub>кВН</sub> +"}, {"t": "p", "s": "(3.6) uкСН − uкВС)", "h": "(3.6) u<sub>кСН</sub> − u<sub>кВС</sub>)"}, {"t": "p", "s": "Эндээс XВ,С,Н = uк(В,С,Н)%·Uн²/(100Sн). Ороомгууд ижил чадалтай (100/100/100 %) бол ороомог бүрийн бодит эсэргүүцэл RВ = RС = RН = ΔPк·Uн²/(2Sн²). Дунд ороомгийн uкС ихэвчлэн тэгтэй ойролцоо эсвэл бага зэрэг сөрөг гардаг — энэ нь орлуулах схемийн математик шинж бөгөөд тооцоонд 0 гэж авна.", "h": "Эндээс X<sub>В,С,Н</sub> = u<sub>к(В,С,Н)</sub>%·U<sub>н</sub>²/(100S<sub>н</sub>). Ороомгууд ижил чадалтай (100/100/100 %) бол ороомог бүрийн бодит эсэргүүцэл R<sub>В</sub> = R<sub>С</sub> = R<sub>Н</sub> = ΔP<sub>к</sub>·U<sub>н</sub>²/(2S<sub>н</sub>²). Дунд ороомгийн u<sub>кС</sub> ихэвчлэн тэгтэй ойролцоо эсвэл бага зэрэг сөрөг гардаг — энэ нь орлуулах схемийн математик шинж бөгөөд тооцоонд 0 гэж авна."}, {"t": "p", "s": "Жишээ 3.3. ТДТН-40000/110/35/10: uкВС = 10.5 %, uкВН = 17 %, uкСН = 6 %, ΔPк = 200 кВт, Uн = 115 кВ.", "h": "<b>Жишээ 3.3. </b>ТДТН-40000/110/35/10: u<sub>кВС</sub> = 10.5 %, u<sub>кВН</sub> = 17 %, u<sub>кСН</sub> = 6 %, ΔP<sub>к</sub> = 200 кВт, U<sub>н</sub> = 115 кВ.", "x": "ex"}, {"t": "p", "s": "uкВ = ½(10.5 + 17 − 6) = 10.75 %; uкС = ½(10.5 + 6 − 17) = −0.25 % ≈ 0; uкН = ½(17 + 6 − 10.5) = 6.25 %.", "h": "u<sub>кВ</sub> = ½(10.5 + 17 − 6) = 10.75 %; u<sub>кС</sub> = ½(10.5 + 6 − 17) = −0.25 % ≈ 0; u<sub>кН</sub> = ½(17 + 6 − 10.5) = 6.25 %.", "x": "ex"}, {"t": "p", "s": "XВ = 10.75·13 225/4000 = 35.5 Ом; XС ≈ 0; XН = 6.25·13 225/4000 = 20.7 Ом; RВ,С,Н = 0.2·13 225/(2·1600) = 0.83 Ом.", "h": "X<sub>В</sub> = 10.75·13 225/4000 = 35.5 Ом; X<sub>С</sub> ≈ 0; X<sub>Н</sub> = 6.25·13 225/4000 = 20.7 Ом; R<sub>В,С,Н</sub> = 0.2·13 225/(2·1600) = 0.83 Ом.", "x": "ex"}, {"t": "p", "s": "Од хэлбэрийн дундын цэг нь тогтсон горимын тооцоонд нэмэлт (дотоод) зангилаа болно.", "h": "Од хэлбэрийн дундын цэг нь тогтсон горимын тооцоонд нэмэлт (дотоод) зангилаа болно.", "x": "ex"}, {"t": "p", "s": "Жишээ 3.6. Гурван ороомогт трансформаторын алдагдал. Жишээ 3.3-ын ТДТН-40000/110/35/10 трансформаторын дунд (35 кВ) талд 15 + j9 МВА, нам (10 кВ) талд 10 + j6 МВА ачаалал байна. ΔPх = 39 кВт, Iх = 0.6 %. Ороомог бүрийн ба нийт алдагдлыг олно уу (115 кВ-оор ойролцоолно).", "h": "<b>Жишээ 3.6. Гурван ороомогт трансформаторын алдагдал. </b>Жишээ 3.3-ын ТДТН-40000/110/35/10 трансформаторын дунд (35 кВ) талд 15 + j9 МВА, нам (10 кВ) талд 10 + j6 МВА ачаалал байна. ΔP<sub>х</sub> = 39 кВт, I<sub>х</sub> = 0.6 %. Ороомог бүрийн ба нийт алдагдлыг олно уу (115 кВ-оор ойролцоолно).", "x": "ex"}, {"t": "p", "s": "Цацраг бүрээр гүйх чадал: В — 25 + j15 (нийлбэр), С — 15 + j9, Н — 10 + j6 МВА.", "h": "Цацраг бүрээр гүйх чадал: В — 25 + j15 (нийлбэр), С — 15 + j9, Н — 10 + j6 МВА.", "x": "ex"}, {"t": "tbl", "s": "", "head": ["Цацраг", "S, МВА", "R, Ом", "X, Ом", "ΔP, кВт", "ΔQ, Мвар"], "rows": [["В", "29.15", "0.83", "35.5", "53.3", "2.282"], ["С", "17.49", "0.83", "0", "19.2", "0"], ["Н", "11.66", "0.83", "20.7", "8.5", "0.213"], ["Соронзлох салаа", "—", "—", "—", "39.0", "0.240"], ["Нийт", "", "", "", "120.0", "2.735"]]}, {"t": "p", "s": "Нийт бодит чадлын алдагдал 0.12 МВт (дамжуулсан 25 МВт-ын 0.48 %), идэвхгүй чадлын алдагдал 2.74 Мвар (ачааллын 15 Мвар-ын 18 %). Дээд ороомгийн цацраг нийт", "h": "Нийт бодит чадлын алдагдал 0.12 МВт (дамжуулсан 25 МВт-ын 0.48 %), идэвхгүй чадлын алдагдал 2.74 Мвар (ачааллын 15 Мвар-ын 18 %). Дээд ороомгийн цацраг нийт", "x": "ex"}, {"t": "p", "s": "чадлыг дамжуулдаг тул алдагдлын дийлэнх нь түүнд ногдоно.", "h": "чадлыг дамжуулдаг тул алдагдлын дийлэнх нь түүнд ногдоно.", "x": "ex"}, {"t": "h", "l": 1, "s": "6. Автотрансформатор", "h": "<b>6. Автотрансформатор</b>"}, {"t": "p", "s": "Автотрансформаторын дээд ба дунд хүчдэлийн ороомог нэгдмэл (цуваа ороомог + нийтлэг ороомог) тул чадлын нэг хэсэг цахилгаанаар шууд, үлдсэн хэсэг нь соронзон замаар дамжина. Хэрэглэх коэффициент α = 1 − UС/UВ (220/110 кВ-д 0.5) нь соронзон замаар дамжих хэсгийг (төрөл чадал Sт = αSн) тодорхойлох ба автотрансформатор ижил чадалтай трансформатороос хөнгөн, хямд, алдагдал багатай. Гуравдагч (нам) ороомог нь төрөл чадалтай, гурвалжин холболттой бөгөөд компенсатор, дотоод хэрэгцээг тэжээнэ.", "h": "Автотрансформаторын дээд ба дунд хүчдэлийн ороомог нэгдмэл (цуваа ороомог + нийтлэг ороомог) тул чадлын нэг хэсэг цахилгаанаар шууд, үлдсэн хэсэг нь соронзон замаар дамжина. <b>Хэрэглэх коэффициент </b>α = 1 − U<sub>С</sub>/U<sub>В</sub> (220/110 кВ-д 0.5) нь соронзон замаар дамжих хэсгийг (<b>төрөл чадал </b>S<sub>т</sub> = αS<sub>н</sub>) тодорхойлох ба автотрансформатор ижил чадалтай трансформатороос хөнгөн, хямд, алдагдал багатай. Гуравдагч (нам) ороомог нь төрөл чадалтай, гурвалжин холболттой бөгөөд компенсатор, дотоод хэрэгцээг тэжээнэ."}, {"t": "p", "s": "Орлуулах схем нь гурван ороомогт трансформаторынхтой ижил. Паспортын uкВН, uкСН-ийг заримдаа төрөл чадалд өгдөг тул нэрлэсэн чадалд шилжүүлэхдээ 1/α-аар үржүүлнэ.", "h": "Орлуулах схем нь гурван ороомогт трансформаторынхтой ижил. Паспортын u<sub>кВН</sub>, u<sub>кСН</sub>-ийг заримдаа төрөл чадалд өгдөг тул нэрлэсэн чадалд шилжүүлэхдээ 1/α-аар үржүүлнэ."}, {"t": "p", "s": "Жишээ. АТДЦТН-125000/220/110: uкВС = 11 %, uкВН = 31 %, uкСН = 19 % (нэрлэсэн чадалд). uкВ = 11.5 %, uкС = −0.5 % ≈ 0, uкН = 19.5 %; XВ = 11.5·230²/(100·125) = 48.7 Ом (230 кВ талд).", "h": "<b>Жишээ. </b>АТДЦТН-125000/220/110: u<sub>кВС</sub> = 11 %, u<sub>кВН</sub> = 31 %, u<sub>кСН</sub> = 19 % (нэрлэсэн чадалд). u<sub>кВ</sub> = 11.5 %, u<sub>кС</sub> = −0.5 % ≈ 0, u<sub>кН</sub> = 19.5 %; X<sub>В</sub> = 11.5·230²/(100·125) = 48.7 Ом (230 кВ талд)."}, {"t": "h", "l": 1, "s": "7. Хувиргалтын коэффициент ба хүчдэлийн тохируулга", "h": "<b>7. Хувиргалтын коэффициент ба хүчдэлийн тохируулга</b>"}, {"t": "p", "s": "Хувиргалтын коэффициент k = Uвн/Uнн нь хоосон явалтын үеийн хүчдэлүүдийн харьцаа. Хүчдэлийг тохируулахын тулд дээд хүчдэлийн ороомогт салбар (отпайка) хийж, ороомгийн тоог өөрчилнө:", "h": "<b>Хувиргалтын коэффициент </b>k = U<sub>вн</sub>/U<sub>нн</sub> нь хоосон явалтын үеийн хүчдэлүүдийн харьцаа. Хүчдэлийг тохируулахын тулд дээд хүчдэлийн ороомогт салбар (отпайка) хийж, ороомгийн тоог өөрчилнө:"}, {"t": "p", "s": "РПН (ачаалал дор шилжүүлэгч) — ихэвчлэн ±9×1.78 % (110 кВ), ±8×1.5 % (220 кВ); автомат тохируулагч (АРКТ) нам талын хүчдэлийг барина.", "h": "<b>РПН </b>(ачаалал дор шилжүүлэгч) — ихэвчлэн ±9×1.78 % (110 кВ), ±8×1.5 % (220 кВ); автомат тохируулагч (АРКТ) нам талын хүчдэлийг барина."}, {"t": "p", "s": "ПБВ (ачаалалгүй үед шилжүүлэх) — ±2×2.5 %; улирлын тохируулгад.", "h": "<b>ПБВ </b>(ачаалалгүй үед шилжүүлэх) — ±2×2.5 %; улирлын тохируулгад."}, {"t": "eq", "s": "Uсалбар = Uвн,н·(1 + n·Δu/100) ; k = Uсалбар/Uнн,н (3.7)", "h": "U<sub>салбар</sub> = U<sub>вн,н</sub>·(1 + n·Δu/100) ; k = U<sub>салбар</sub>/U<sub>нн,н</sub> (3.7)", "n": "3.7", "img": "data:image/png;base64,", "iw": 504}, {"t": "p", "s": "Салбар сонгох. Дээд хүчдэлд шилжүүлсэн нам талын хүчдэл U′2 (уналтыг хассан), хүссэн нам талын хүчдэл U2ж бол шаардлагатай салбарын хүчдэл Uсалб = U′2·Uнн,н/U2ж.", "h": "<b>Салбар сонгох. </b>Дээд хүчдэлд шилжүүлсэн нам талын хүчдэл U′<sub>2</sub> (уналтыг хассан), хүссэн нам талын хүчдэл U<sub>2ж</sub> бол шаардлагатай салбарын хүчдэл U<sub>салб</sub> = U′<sub>2</sub>·U<sub>нн,н</sub>/U<sub>2ж</sub>."}, {"t": "p", "s": "Жишээ 3.2-т U′2 = 108.9 кВ, хүссэн 10.5 кВ бол Uсалб = 108.9·11/10.5 = 114.1 кВ; 115 кВоос (114.1 − 115)/115 = −0.8 % → РПН-ий 0 эсвэл −1 салбар (−1.78 %, 112.95 кВ). −1 салбарт U2 = 108.9·11/112.95 = 10.60 кВ.", "h": "Жишээ 3.2-т U′<sub>2</sub> = 108.9 кВ, хүссэн 10.5 кВ бол U<sub>салб</sub> = 108.9·11/10.5 = 114.1 кВ; 115 кВоос (114.1 − 115)/115 = −0.8 % → РПН-ий 0 эсвэл −1 салбар (−1.78 %, 112.95 кВ). −1 салбарт U<sub>2</sub> = 108.9·11/112.95 = 10.60 кВ.", "x": "ex"}, {"t": "h", "l": 1, "s": "8. Хувиргалтын коэффициентыг тооцоонд оруулах — хамгийн", "h": "<b>8. Хувиргалтын коэффициентыг тооцоонд оруулах — хамгийн</b>"}, {"t": "h", "l": 1, "s": "тохиромжтой трансформатортой П схем", "h": "<b>тохиромжтой трансформатортой П схем</b>"}, {"t": "p", "s": "Олон хүчдэлийн түвшинтэй сүлжээг нэг схемд тооцоолохын тулд трансформаторын эсэргүүцлийг нэг талд шилжүүлж, нэрлэсэн бус коэффициентыг хамгийн тохиромжтой трансформатороор (эсэргүүцэлгүй, алдагдалгүй, зөвхөн хүчдэлийг k:1 харьцаагаар", "h": "Олон хүчдэлийн түвшинтэй сүлжээг нэг схемд тооцоолохын тулд трансформаторын эсэргүүцлийг нэг талд шилжүүлж, нэрлэсэн бус коэффициентыг <b>хамгийн тохиромжтой</b> <b>трансформатороор </b>(эсэргүүцэлгүй, алдагдалгүй, зөвхөн хүчдэлийг k:1 харьцаагаар"}, {"t": "p", "s": "хувиргана) төлөөлнө. Нэгжийн харьцангуй системд нэрлэсэн коэффициент 1 болж, нэрлэсэн бус хэсэг k* = k/kн (жишээ нь 1.0178) үлдэнэ.", "h": "хувиргана) төлөөлнө. Нэгжийн харьцангуй системд нэрлэсэн коэффициент 1 болж, нэрлэсэн бус хэсэг k* = k/k<sub>н</sub> (жишээ нь 1.0178) үлдэнэ."}, {"t": "p", "s": "Зангилаа i нь k*-тай тал, j нь эсэргүүцэлтэй тал, y = 1/zт гэвэл Кирхгофын хуулиас:", "h": "Зангилаа i нь k*-тай тал, j нь эсэргүүцэлтэй тал, y = 1/z<sub>т</sub> гэвэл Кирхгофын хуулиас:"}, {"t": "p", "s": "İi y/k² −y/k U̇ i", "h": "İ<sub>i</sub> y/k² −y/k U̇ <sub>i</sub>"}, {"t": "p", "s": "= · (3.8) İj −y/k y U̇ j", "h": "= · (3.8) İ<sub>j</sub> −y/k y U̇ <sub>j</sub>"}, {"t": "p", "s": "Энэ 2×2 матриц нь трансформаторын Y матрицад оруулах хувь нэмэр юм (лекц 7). Түүнийг П схемээр дүрсэлбэл: цуваа салаа y/k, i талын хөндлөн салаа y(1 − k)/k², j талын хөндлөн салаа y(k − 1)/k. k = 1 үед хөндлөн салаа алга болж ердийн цуваа эсэргүүцэл үлдэнэ. Хөндлөн салаа нь физик элемент биш, харин хувиргалтаас үүсэх идэвхгүй чадлын дахин хуваарилалтыг илэрхийлнэ. Лабораторийн стендийн шугамын хүснэгтийн «k» багана яг энэ k*-г оруулдаг.", "h": "Энэ 2×2 матриц нь трансформаторын Y матрицад оруулах хувь нэмэр юм (лекц 7). Түүнийг П схемээр дүрсэлбэл: цуваа салаа y/k, i талын хөндлөн салаа y(1 − k)/k², j талын хөндлөн салаа y(k − 1)/k. k = 1 үед хөндлөн салаа алга болж ердийн цуваа эсэргүүцэл үлдэнэ. Хөндлөн салаа нь физик элемент биш, харин хувиргалтаас үүсэх идэвхгүй чадлын дахин хуваарилалтыг илэрхийлнэ. Лабораторийн стендийн шугамын хүснэгтийн «k» багана яг энэ k*-г оруулдаг."}, {"t": "p", "s": "Жишээ 3.4. Матриц хэлбэрээр. ТДН-16000/110 (жишээ 3.1), Sб = 100 МВА, Uб = 115 кВ (Zб = 132.25 Ом). РПН +2 салбар (+3.56 %, k* = 1.0356). Трансформаторын Y матрицыг ол.", "h": "<b>Жишээ 3.4. Матриц хэлбэрээр. </b>ТДН-16000/110 (жишээ 3.1), S<sub>б</sub> = 100 МВА, U<sub>б</sub> = 115 кВ (Z<sub>б</sub> = 132.25 Ом). РПН +2 салбар (+3.56 %, k* = 1.0356). Трансформаторын Y матрицыг ол.", "x": "ex"}, {"t": "p", "s": "1. zт = (4.39 + j86.8)/132.25 = 0.0332 + j0.6563 о.н.; y = 1/zт = 0.0769 − j1.5197 о.н.", "h": "1. z<sub>т</sub> = (4.39 + j86.8)/132.25 = 0.0332 + j0.6563 о.н.; y = 1/z<sub>т</sub> = 0.0769 − j1.5197 о.н.", "x": "ex"}, {"t": "p", "s": "2. y/k² = (0.0769 − j1.5197)/1.0725 = 0.0717 − j1.4170; −y/k = −0.0742 + j1.4675.", "h": "2. y/k² = (0.0769 − j1.5197)/1.0725 = 0.0717 − j1.4170; −y/k = −0.0742 + j1.4675.", "x": "ex"}, {"t": "p", "s": "0.0717 − j1.4170 −0.0742 + j1.4675 Yт = (3.9)", "h": "0.0717 − j1.4170 −0.0742 + j1.4675 <b>Y</b><sub>т</sub> = (3.9)", "x": "ex"}, {"t": "p", "s": "−0.0742 + j1.4675 0.0769 − j1.5197", "h": "−0.0742 + j1.4675 0.0769 − j1.5197", "x": "ex"}, {"t": "p", "s": "3. П схемийн хөндлөн салаа: i тал: y(1 − k)/k² = −0.0026 + j0.0504 (багтаамжийн шинжтэй); j тал: y(k − 1)/k = 0.0026 − j0.0522 (индуктив шинжтэй). Мөр бүрийн нийлбэр тэг биш болсон нь хөндлөн салааны нөлөө юм.", "h": "3. П схемийн хөндлөн салаа: i тал: y(1 − k)/k² = −0.0026 + j0.0504 (багтаамжийн шинжтэй); j тал: y(k − 1)/k = 0.0026 − j0.0522 (индуктив шинжтэй). Мөр бүрийн нийлбэр тэг биш болсон нь хөндлөн салааны нөлөө юм.", "x": "ex"}, {"t": "p", "s": "4. Соронзлох салаа (i талд нэмнэ): (Gт − jBт)·Zб = (1.44 − j8.47)·10⁻⁶·132.25 = 0.00019 − j0.00112 о.н. — ихэвчлэн ΔṠх ачаалал болгон оруулна.", "h": "4. Соронзлох салаа (i талд нэмнэ): (G<sub>т</sub> − jB<sub>т</sub>)·Z<sub>б</sub> = (1.44 − j8.47)·10⁻⁶·132.25 = 0.00019 − j0.00112 о.н. — ихэвчлэн ΔṠ<sub>х</sub> ачаалал болгон оруулна.", "x": "ex"}, {"t": "h", "l": 1, "s": "9. Трансформаторын зэрэгцээ ажиллагаа", "h": "<b>9. Трансформаторын зэрэгцээ ажиллагаа</b>"}, {"t": "p", "s": "Трансформаторыг зэрэгцээ ажиллуулахад (1) хувиргалтын коэффициент тэнцүү, (2) uк% тэнцүү (±10 %), (3) ороомгийн холболтын бүлэг ижил байх шаардлагатай. Коэффициент ялгаатай бол ачааллаас үл хамааран тэгшитгэх гүйдэл гүйнэ:", "h": "Трансформаторыг зэрэгцээ ажиллуулахад (1) хувиргалтын коэффициент тэнцүү, (2) u<sub>к</sub>% тэнцүү (±10 %), (3) ороомгийн холболтын бүлэг ижил байх шаардлагатай. Коэффициент ялгаатай бол ачааллаас үл хамааран <b>тэгшитгэх гүйдэл </b>гүйнэ:"}, {"t": "eq", "s": "Iтэг ≈ Δk%·Iн/(uк1% + uк2%)·100 (3.10)", "h": "I<sub>тэг</sub> ≈ Δk%·I<sub>н</sub>/(u<sub>к1</sub>% + u<sub>к2</sub>%)·100 (3.10)", "n": "3.10", "img": "data:image/png;base64,", "iw": 449}, {"t": "p", "s": "Жишээ нь хоёр ТДН-16000 трансформаторын салбар 1 алхмаар (1.78 %) ялгаатай бол Iтэг ≈ 1.78/21·100 = 8.5 % Iн — алдагдал нэмэгдэж, нэг нь хэт ачаалагдана. uк ялгаатай бол ачаалал uк-д урвуу пропорциональ хуваарилагдана.", "h": "Жишээ нь хоёр ТДН-16000 трансформаторын салбар 1 алхмаар (1.78 %) ялгаатай бол I<sub>тэг</sub> ≈ 1.78/21·100 = 8.5 % I<sub>н</sub> — алдагдал нэмэгдэж, нэг нь хэт ачаалагдана. u<sub>к</sub> ялгаатай бол ачаалал u<sub>к</sub>-д урвуу пропорциональ хуваарилагдана."}, {"t": "p", "s": "Зэрэгцээ ажиллах оновчтой тоо. n ба n + 1 трансформатортой үеийн алдагдал тэнцэх ачаалал Sхил = Sн√(n(n + 1)ΔPх/ΔPк). ТДН-16000-д n = 1: Sхил = 16·√(2·19/85) = 10.7 МВА. Ачаалал 10.7 МВА-аас бага үед (шөнө, зун) нэг трансформаторыг салгах нь алдагдлыг бууруулна (лекц 12).", "h": "<b>Зэрэгцээ ажиллах оновчтой тоо. </b>n ба n + 1 трансформатортой үеийн алдагдал тэнцэх ачаалал S<sub>хил</sub> = S<sub>н</sub>√(n(n + 1)ΔP<sub>х</sub>/ΔP<sub>к</sub>). ТДН-16000-д n = 1: S<sub>хил</sub> = 16·√(2·19/85) = 10.7 МВА. Ачаалал 10.7 МВА-аас бага үед (шөнө, зун) нэг трансформаторыг салгах нь алдагдлыг бууруулна (лекц 12)."}, {"t": "h", "l": 1, "s": "10. Трансформаторын нэгжийн харьцангуй параметр", "h": "<b>10. Трансформаторын нэгжийн харьцангуй параметр</b>"}, {"t": "p", "s": "Нэгжийн харьцангуй системд (лекц 4) трансформаторын параметр хүчдэлийн аль талд шилжүүлснээс хамаарахгүй — давуу тал. Өөрийн сууриар: x* = uк%/100, r* = ΔPк/Sн. Системийн суурь Sб-д: x*б = (uк%/100)·(Sб/Sн)·(Uн/Uб)². Жишээ 3.1-д x* = 0.105·100/16 = 0.656 о.н. — жишээ 3.4-ийн 0.6563-тай тохирч байна.", "h": "Нэгжийн харьцангуй системд (лекц 4) трансформаторын параметр хүчдэлийн аль талд шилжүүлснээс хамаарахгүй — давуу тал. Өөрийн сууриар: x* = u<sub>к</sub>%/100, r* = ΔP<sub>к</sub>/S<sub>н</sub>. Системийн суурь S<sub>б</sub>-д: x*<sub>б</sub> = (u<sub>к</sub>%/100)·(S<sub>б</sub>/S<sub>н</sub>)·(U<sub>н</sub>/U<sub>б</sub>)². Жишээ 3.1-д x* = 0.105·100/16 = 0.656 о.н. — жишээ 3.4-ийн 0.6563-тай тохирч байна."}, {"t": "tbl", "s": "", "head": ["Элемент", "R, Ом", "X, Ом", "X, о.н. (100 МВА)", "ΔQ , Мвар х"], "rows": [["ТДН-10000/110", "7.94", "138.9", "1.050", "0.070"], ["ТДН-16000/110", "4.39", "86.8", "0.656", "0.112"], ["ТРДН-25000/110", "2.54", "55.5", "0.420", "0.175"], ["ТРДН-40000/110", "1.42", "34.7", "0.263", "0.260"]]}, {"t": "cap", "s": "Хүснэгт 3.2. Трансформаторын параметр (115 кВ талд)", "h": "Хүснэгт 3.2. Трансформаторын параметр (115 кВ талд)"}, {"t": "h", "l": 1, "s": "11. Шугам ба трансформаторын гинжин хэлхээ — матрицын үржвэр", "h": "<b>11. Шугам ба трансформаторын гинжин хэлхээ — матрицын үржвэр</b>"}, {"t": "p", "s": "Лекц 2-т шугамыг ABCD матрицаар илэрхийлсэн. Трансформаторын цуваа эсэргүүцлийг (соронзлох салааг ачаалал болгосон үед) богино шугам шиг [1 Zт; 0 1] матрицаар илэрхийлбэл «шугам + трансформатор» хэлхээний матриц нь хоёр матрицын үржвэр болно. Энэ нь дэд станцыг тэжээх радиаль хэлхээг нэг алхмаар тооцох боломж олгоно.", "h": "Лекц 2-т шугамыг ABCD матрицаар илэрхийлсэн. Трансформаторын цуваа эсэргүүцлийг (соронзлох салааг ачаалал болгосон үед) богино шугам шиг [1 Z<sub>т</sub>; 0 1] матрицаар илэрхийлбэл «шугам + трансформатор» хэлхээний матриц нь хоёр матрицын <b>үржвэр </b>болно. Энэ нь дэд станцыг тэжээх радиаль хэлхээг нэг алхмаар тооцох боломж олгоно."}, {"t": "p", "s": "Жишээ 3.5. 110 кВ шугам (лекц 2, жишээ 2.2: Zл = 16.2 + j41.0 Ом, Yл = j2.78·10⁻⁴ См)аар ТДН-16000/110 трансформатор (Zт = 4.39 + j86.8 Ом) тэжээгдэнэ. Нам талд 10.5 кВ, ачаалал 12 + j8 МВА. Эхлэлийн хүчдэл ба чадлыг олно уу (k = 115/11).", "h": "<b>Жишээ 3.5. </b>110 кВ шугам (лекц 2, жишээ 2.2: Z<sub>л</sub> = 16.2 + j41.0 Ом, Y<sub>л</sub> = j2.78·10⁻⁴ См)аар ТДН-16000/110 трансформатор (Z<sub>т</sub> = 4.39 + j86.8 Ом) тэжээгдэнэ. Нам талд 10.5 кВ, ачаалал 12 + j8 МВА. Эхлэлийн хүчдэл ба чадлыг олно уу (k = 115/11).", "x": "ex"}, {"t": "p", "s": "1. Хэлхээний матриц:", "h": "1. Хэлхээний матриц:", "x": "ex"}, {"t": "p", "s": "0.9943 + j0.0023 16.2 + j41.0 1 4.39 + j86.8 M = · =", "h": "0.9943 + j0.0023 16.2 + j41.0 1 4.39 + j86.8 <b>M </b>= · =", "x": "ex"}, {"t": "p", "s": "j2.80·10⁻⁴ 0.9943 + j0.0023 0 1", "h": "j2.80·10⁻⁴ 0.9943 + j0.0023 0 1", "x": "ex"}, {"t": "p", "s": "(3.11) 0.9943 + j0.0023 20.37 + j127.32", "h": "(3.11) 0.9943 + j0.0023 20.37 + j127.32", "x": "ex"}, {"t": "p", "s": "j2.80·10⁻⁴ 0.9702 + j0.0034", "h": "j2.80·10⁻⁴ 0.9702 + j0.0034", "x": "ex"}, {"t": "p", "s": "2. Төгсгөлийн хэмжигдэхүүн (110 кВ талд шилжүүлсэн): U′2 = 10.5·115/11 = 109.77 кВ, фазын 63.38 кВ; İ2 = (12 − j8)/(3·63.38) = 0.0631 − j0.0421 кА.", "h": "2. Төгсгөлийн хэмжигдэхүүн (110 кВ талд шилжүүлсэн): U′<sub>2</sub> = 10.5·115/11 = 109.77 кВ, фазын 63.38 кВ; İ<sub>2</sub> = (12 − j8)/(3·63.38) = 0.0631 − j0.0421 кА.", "x": "ex"}, {"t": "p", "s": "3. Үр дүн: [U̇ 1ф; İ1] = M·[U̇ 2ф; İ2] → U1 = 121.3 кВ, δ = 6.0°; Ṡ1 = 12.32 + j6.16 МВА.", "h": "3. Үр дүн: [U̇ <sub>1ф</sub>; İ<sub>1</sub>] = <b>M</b>·[U̇ <sub>2ф</sub>; İ<sub>2</sub>] → U<sub>1</sub> = 121.3 кВ, δ = 6.0°; Ṡ<sub>1</sub> = 12.32 + j6.16 МВА.", "x": "ex"}, {"t": "p", "s": "4. Тайлбар: бодит чадлын алдагдал 0.32 МВт (шугамд ≈ 0.24, трансформаторын ороомогт ≈ 0.08 МВт; соронзлох алдагдал 0.019 МВт-ыг тусад нь нэмнэ). Эхлэлийн идэвхгүй чадал ачааллынхаас 1.84 Мвар-аар бага: шугамын цэнэглэх чадал (≈ 4.1 Мвар) нь шугам ба трансформаторын I²X алдагдлаас (≈ 2.3 Мвар) их байгаа нь бага ачааллын 110 кВ шугамын онцлог. Хэрэглэгчийн шинд 10.5 кВ барихын тулд эхлэлд 121.3 кВ шаардлагатай — энэ нь 126 кВ-ын хязгаарт ойр тул РПН-ийн салбарыг (+2 … +3) ашиглаж эхлэлийн хүчдэлийг бууруулах нь зүйтэй.", "h": "4. Тайлбар: бодит чадлын алдагдал 0.32 МВт (шугамд ≈ 0.24, трансформаторын ороомогт ≈ 0.08 МВт; соронзлох алдагдал 0.019 МВт-ыг тусад нь нэмнэ). Эхлэлийн идэвхгүй чадал ачааллынхаас 1.84 Мвар-аар бага: шугамын цэнэглэх чадал (≈ 4.1 Мвар) нь шугам ба трансформаторын I²X алдагдлаас (≈ 2.3 Мвар) их байгаа нь бага ачааллын 110 кВ шугамын онцлог. Хэрэглэгчийн шинд 10.5 кВ барихын тулд эхлэлд 121.3 кВ шаардлагатай — энэ нь 126 кВ-ын хязгаарт ойр тул РПН-ийн салбарыг (+2 … +3) ашиглаж эхлэлийн хүчдэлийг бууруулах нь зүйтэй.", "x": "ex"}, {"t": "h", "l": 1, "s": "12. Фаз шилжүүлэгч трансформатор", "h": "<b>12. Фаз шилжүүлэгч трансформатор</b>"}, {"t": "p", "s": "Зэрэгцээ шугамуудын хооронд бодит чадлын урсгалыг удирдахын тулд хүчдэлийн өнцгийг шилжүүлэх (фаз шилжүүлэгч) трансформатор хэрэглэдэг. Түүний хувиргалтын коэффициент комплекс тоо: k̇ = k∠φ. Энэ үед (3.8) матриц тэгш хэмгүй болно:", "h": "Зэрэгцээ шугамуудын хооронд бодит чадлын урсгалыг удирдахын тулд хүчдэлийн өнцгийг шилжүүлэх (<b>фаз шилжүүлэгч</b>) трансформатор хэрэглэдэг. Түүний хувиргалтын коэффициент комплекс тоо: k̇ = k∠φ. Энэ үед (3.8) матриц <b>тэгш хэмгүй </b>болно:"}, {"t": "p", "s": "İi y/|k|² −y/k̇ * U̇ i", "h": "İ<sub>i</sub> y/|k|² −y/k̇ * U̇ <sub>i</sub>"}, {"t": "p", "s": "= · (3.12) İj −y/k̇ y U̇ j", "h": "= · (3.12) İ<sub>j</sub> −y/k̇ y U̇ <sub>j</sub>"}, {"t": "p", "s": "Жишээ нь y = −j10, k̇ = 1∠5° бол Yij = −0.872 + j9.962, Yji = 0.872 + j9.962 — хуурмаг хэсэг тэнцүү боловч бодит хэсэг эсрэг тэмдэгтэй. Иймд фаз шилжүүлэгчтэй сүлжээний Y матриц тэгш хэмгүй болж, тэгш хэмт матрицад зориулсан хэмнэлттэй аргыг (лекц 8) шууд хэрэглэх боломжгүй. Шилжүүлэх өнцөг φ = 5° нь ойролцоогоор P ≈ φ/x = 0.0873/0.1 = 0.87 о.н. (87 МВт) нэмэлт урсгалыг шугамаар албадан дамжуулна.", "h": "Жишээ нь y = −j10, k̇ = 1∠5° бол Y<sub>ij</sub> = −0.872 + j9.962, Y<sub>ji</sub> = 0.872 + j9.962 — хуурмаг хэсэг тэнцүү боловч бодит хэсэг эсрэг тэмдэгтэй. Иймд фаз шилжүүлэгчтэй сүлжээний Y матриц тэгш хэмгүй болж, тэгш хэмт матрицад зориулсан хэмнэлттэй аргыг (лекц 8) шууд хэрэглэх боломжгүй. Шилжүүлэх өнцөг φ = 5° нь ойролцоогоор P ≈ φ/x = 0.0873/0.1 = 0.87 о.н. (87 МВт) нэмэлт урсгалыг шугамаар албадан дамжуулна."}, {"t": "h", "l": 1, "s": "13. Хуваагдмал ороомогт трансформатор ба зэрэгцээ ажиллагааны", "h": "<b>13. Хуваагдмал ороомогт трансформатор ба зэрэгцээ ажиллагааны</b>"}, {"t": "h", "l": 1, "s": "алдагдал", "h": "<b>алдагдал</b>"}, {"t": "p", "s": "ТРДН төрлийн 25–63 МВА трансформаторын нам талын ороомог хоёр хуваагдсан байдаг. Энэ нь 6–10 кВ талын богино залгааны гүйдлийг хязгаарлаж, хоёр бие даасан секцийг тэжээх боломж олгоно. Орлуулах схем нь од хэлбэрийн: XВ = 0.125Xт, XН1 = XН2 = 1.75Xт (хуваагдлын коэффициент 3.5 үед), энд Xт нь паспортын uк-аар тооцсон нийт утга. Хоёр секц ижил ачаалалтай тогтсон горимд энэ нь нийт Xт-тэй ердийн трансформатортой тэнцэнэ.", "h": "ТРДН төрлийн 25–63 МВА трансформаторын нам талын ороомог хоёр хуваагдсан байдаг. Энэ нь 6–10 кВ талын богино залгааны гүйдлийг хязгаарлаж, хоёр бие даасан секцийг тэжээх боломж олгоно. Орлуулах схем нь од хэлбэрийн: X<sub>В</sub> = 0.125X<sub>т</sub>, X<sub>Н1</sub> = X<sub>Н2</sub> = 1.75X<sub>т</sub> (хуваагдлын коэффициент 3.5 үед), энд X<sub>т</sub> нь паспортын u<sub>к</sub>-аар тооцсон нийт утга. Хоёр секц ижил ачаалалтай тогтсон горимд энэ нь нийт X<sub>т</sub>-тэй ердийн трансформатортой тэнцэнэ."}, {"t": "p", "s": "Зэрэгцээ ажиллагааны оновчтой тоог (9-р бүлэг) хүснэгтээр харуулъя (ТДН-16000/110, кВт):", "h": "Зэрэгцээ ажиллагааны оновчтой тоог (9-р бүлэг) хүснэгтээр харуулъя (ТДН-16000/110, кВт):"}, {"t": "tbl", "s": "", "head": ["Ачаалал S, МВА", "4", "8", "10.7", "12", "16", "20"], "rows": [["1 трансформатор, ΔP", "24.3", "40.2", "57.0", "66.8", "104.0", "151.8*"], ["2 трансформатор, ΔP", "40.7", "48.6", "57.0", "61.9", "80.5", "104.4"]]}, {"t": "cap", "s": "Хүснэгт 3.3. Трансформаторын тооноос хамаарах алдагдал (* — хэт ачаалал)", "h": "Хүснэгт 3.3. Трансформаторын тооноос хамаарах алдагдал (* — хэт ачаалал)"}, {"t": "p", "s": "10.7 МВА-аас бага ачаалалд нэг трансформатор ажиллуулахад алдагдал бага. Гэвч найдвартай байдлын үүднээс (N−1) хоёр трансформатортой дэд станцад нэгийг салгахдаа", "h": "10.7 МВА-аас бага ачаалалд нэг трансформатор ажиллуулахад алдагдал бага. Гэвч найдвартай байдлын үүднээс (N−1) хоёр трансформатортой дэд станцад нэгийг салгахдаа"}, {"t": "p", "s": "нөөц автомат залгалт (АВР) байгаа эсэхийг харгалзана.", "h": "нөөц автомат залгалт (АВР) байгаа эсэхийг харгалзана."}, {"t": "h", "l": 1, "s": "14. Ороомгийн холболтын бүлэг ба фазын шилжилт", "h": "<b>14. Ороомгийн холболтын бүлэг ба фазын шилжилт</b>"}, {"t": "p", "s": "Гурван фазын трансформаторын ороомгийг од (Y, YN) эсвэл гурвалжин (Δ) холболттой хийдэг. Y/Δ холболттой трансформатор (жишээ нь YN/Δ-11) нь дээд ба нам талын шугамын хүчдэлийн хооронд 30°-ын фазын шилжилт үүсгэнэ: бүлгийн дугаар × 30° (11-р бүлэгт 330° буюу −30°). Тэгш хэмт тогтсон горимын тооцоонд энэ шилжилт бүх хүчдэлийн түвшинд адил нөлөөлж, чадлын урсгалд нөлөөлдөггүй тул ихэвчлэн тооцохгүй. Харин хоёр өөр замаар (жишээ нь YN/Δ-11 ба YN/Y-0 трансформатороор) холбогдсон цагираг сүлжээнд 30°-ын ялгаа маш их тэгшитгэх гүйдэл үүсгэх тул ийм холболтыг хориглоно — зэрэгцээ ажиллагааны 3-р нөхцөл.", "h": "Гурван фазын трансформаторын ороомгийг од (Y, YN) эсвэл гурвалжин (Δ) холболттой хийдэг. Y/Δ холболттой трансформатор (жишээ нь YN/Δ-11) нь дээд ба нам талын шугамын хүчдэлийн хооронд 30°-ын фазын шилжилт үүсгэнэ: бүлгийн дугаар × 30° (11-р бүлэгт 330° буюу −30°). Тэгш хэмт тогтсон горимын тооцоонд энэ шилжилт бүх хүчдэлийн түвшинд адил нөлөөлж, чадлын урсгалд нөлөөлдөггүй тул ихэвчлэн <b>тооцохгүй</b>. Харин хоёр өөр замаар (жишээ нь YN/Δ-11 ба YN/Y-0 трансформатороор) холбогдсон цагираг сүлжээнд 30°-ын ялгаа маш их тэгшитгэх гүйдэл үүсгэх тул ийм холболтыг хориглоно — зэрэгцээ ажиллагааны 3-р нөхцөл."}, {"t": "p", "s": "Тэг дарааллын горимд холболт шийдвэрлэх ач холбогдолтой: YN талаас тэг дарааллын гүйдэл трансформаторт орж, Δ ороомогт эргэлдэнэ; Y (газардуулаагүй) ба Δ талаас тэг дарааллын гүйдэл дамжихгүй. Энэ нь газардлагын гэмтлийн гүйдэл, хамгаалалтын тохируулгыг тодорхойлдог (Релейн хамгаалалт хичээл).", "h": "Тэг дарааллын горимд холболт шийдвэрлэх ач холбогдолтой: YN талаас тэг дарааллын гүйдэл трансформаторт орж, Δ ороомогт эргэлдэнэ; Y (газардуулаагүй) ба Δ талаас тэг дарааллын гүйдэл дамжихгүй. Энэ нь газардлагын гэмтлийн гүйдэл, хамгаалалтын тохируулгыг тодорхойлдог (Релейн хамгаалалт хичээл)."}, {"t": "h", "l": 1, "s": "15. Трансформаторын ачааллын даац ба хэт ачаалал", "h": "<b>15. Трансформаторын ачааллын даац ба хэт ачаалал</b>"}, {"t": "p", "s": "Трансформаторын нэрлэсэн чадал нь орчны температур +20 °C, ороомгийн хамгийн халуун цэгийн температур 98 °C үед тусгаарлагч нормын хугацаанд (20–25 жил) элэгдэх нөхцөлөөр тодорхойлогдоно. Тусгаарлагчийн элэгдэл температур 6 °C өсөх тутам хоёр дахин хурдасдаг (Монтзингерийн дүрэм). Иймд:", "h": "Трансформаторын нэрлэсэн чадал нь орчны температур +20 °C, ороомгийн хамгийн халуун цэгийн температур 98 °C үед тусгаарлагч нормын хугацаанд (20–25 жил) элэгдэх нөхцөлөөр тодорхойлогдоно. Тусгаарлагчийн элэгдэл температур 6 °C өсөх тутам хоёр дахин хурдасдаг (Монтзингерийн дүрэм). Иймд:"}, {"t": "p", "s": "Систематик хэт ачаалал — хоногийн ачааллын график жигд бус бол оргил үед нэрлэсэн чадлаас хэтрэх, харин бага ачааллын үед элэгдлийг нөхөх; ихэвчлэн 1.2– 1.5·Sн хүртэл хэдэн цаг.", "h": "<b>Систематик хэт ачаалал </b>— хоногийн ачааллын график жигд бус бол оргил үед нэрлэсэн чадлаас хэтрэх, харин бага ачааллын үед элэгдлийг нөхөх; ихэвчлэн 1.2– 1.5·S<sub>н</sub> хүртэл хэдэн цаг."}, {"t": "p", "s": "Ослын хэт ачаалал — зэрэгцээ трансформатор гэмтэхэд 1.4·Sн хүртэл, 5 хоногийн хугацаанд өдөрт 6 цагаас ихгүй (ердийн шаардлага).", "h": "<b>Ослын хэт ачаалал </b>— зэрэгцээ трансформатор гэмтэхэд 1.4·S<sub>н</sub> хүртэл, 5 хоногийн хугацаанд өдөрт 6 цагаас ихгүй (ердийн шаардлага)."}, {"t": "p", "s": "Орчны температурын нөлөө — Монголын өвлийн хүйтэнд (−20…−30 °C) трансформаторын даац нэрлэсэнээс 20–30 %-иар өндөр, зуны халуунд эсрэгээрээ буурна. Өвлийн оргил ачаалал ба өндөр даац давхцдаг нь давуу тал.", "h": "<b>Орчны температурын нөлөө </b>— Монголын өвлийн хүйтэнд (−20…−30 °C) трансформаторын даац нэрлэсэнээс 20–30 %-иар өндөр, зуны халуунд эсрэгээрээ буурна. Өвлийн оргил ачаалал ба өндөр даац давхцдаг нь давуу тал."}, {"t": "p", "s": "Хоёр трансформатортой дэд станцын трансформаторын чадлыг ихэвчлэн Sн ≥ Smax/1.4 нөхцөлөөр сонгоно — нэг нь гэмтэхэд үлдсэн нь 40 %-ийн хэт ачаалалтайгаар бүх хэрэглэгчийг тэжээнэ. Жишээ нь Smax = 20 МВА бол Sн ≥ 14.3 → 2×ТДН-16000. Хүснэгт 3.3-т 20 МВА-д нэг трансформаторын ачааллын коэффициент 1.25 (зөвшөөрөгдөх ослын хэт ачааллын хүрээнд).", "h": "Хоёр трансформатортой дэд станцын трансформаторын чадлыг ихэвчлэн S<sub>н</sub> ≥ S<sub>max</sub>/1.4 нөхцөлөөр сонгоно — нэг нь гэмтэхэд үлдсэн нь 40 %-ийн хэт ачаалалтайгаар бүх хэрэглэгчийг тэжээнэ. Жишээ нь S<sub>max</sub> = 20 МВА бол S<sub>н</sub> ≥ 14.3 → 2×ТДН-16000. Хүснэгт 3.3-т 20 МВА-д нэг трансформаторын ачааллын коэффициент 1.25 (зөвшөөрөгдөх ослын хэт ачааллын хүрээнд)."}, {"t": "p", "s": "Тогтсон горимын тооцооны дараа трансформатор бүрийн ачааллын коэффициент β = S/Sн-ийг шалгаж, хэвийн горимд β ≤ 1.0 (систематик хэт ачааллыг тусад нь үнэлнэ), N−1 горимд β ≤ 1.4 байгааг баталгаажуулна. Лабораторийн стенд үр дүнгийн хүснэгтэд салаа бүрийн гүйдэл, чадлыг гаргадаг тул энэ шалгалтыг шууд хийж болно.", "h": "Тогтсон горимын тооцооны дараа трансформатор бүрийн ачааллын коэффициент β = S/S<sub>н</sub>-ийг шалгаж, хэвийн горимд β ≤ 1.0 (систематик хэт ачааллыг тусад нь үнэлнэ), N−1 горимд β ≤ 1.4 байгааг баталгаажуулна. Лабораторийн стенд үр дүнгийн хүснэгтэд салаа бүрийн гүйдэл, чадлыг гаргадаг тул энэ шалгалтыг шууд хийж болно."}, {"t": "h", "l": 2, "s": "Шугаман тохируулагч ба нэмэлт трансформатор", "h": "<b>Шугаман тохируулагч ба нэмэлт трансформатор</b>"}, {"t": "p", "s": "РПН-гүй трансформатортой дэд станц, эсвэл тусдаа шугамын хүчдэлийг тохируулахын тулд шугаман тохируулагч (нэмэлт трансформатор) хэрэглэдэг. Тэр нь шугамд цуваа холбогдож, үндсэн хүчдэлд ±10–15 % хүртэл нэмэлт хүчдэл (ΔU̇ ) нэмнэ. Нэмэлт хүчдэл үндсэн хүчдэлтэй ижил фазтай бол уртын тохируулга (зөвхөн модуль өөрчлөгдөж, идэвхгүй урсгалд нөлөөлнө), 90°-ын шилжилттэй бол хөндлөн тохируулга (өнцөг өөрчлөгдөж, бодит урсгалд нөлөөлнө — фаз шилжүүлэгчийн зарчим), дурын өнцгөөр бол налуу тохируулга гэнэ. Тооцоонд эдгээрийг комплекс хувиргалтын коэффициент k̇ = 1 + ΔU̇ /U̇ -тэй хамгийн тохиромжтой трансформатороор (3.12) оруулна.", "h": "РПН-гүй трансформатортой дэд станц, эсвэл тусдаа шугамын хүчдэлийг тохируулахын тулд <b>шугаман тохируулагч </b>(нэмэлт трансформатор) хэрэглэдэг. Тэр нь шугамд цуваа холбогдож, үндсэн хүчдэлд ±10–15 % хүртэл нэмэлт хүчдэл (ΔU̇ ) нэмнэ. Нэмэлт хүчдэл үндсэн хүчдэлтэй ижил фазтай бол <b>уртын </b>тохируулга (зөвхөн модуль өөрчлөгдөж, идэвхгүй урсгалд нөлөөлнө), 90°-ын шилжилттэй бол <b>хөндлөн </b>тохируулга (өнцөг өөрчлөгдөж, бодит урсгалд нөлөөлнө — фаз шилжүүлэгчийн зарчим), дурын өнцгөөр бол <b>налуу </b>тохируулга гэнэ. Тооцоонд эдгээрийг комплекс хувиргалтын коэффициент k̇ = 1 + ΔU̇ /U̇ -тэй хамгийн тохиромжтой трансформатороор (3.12) оруулна."}, {"t": "p", "s": "Түгээх сүлжээнд 6–10 кВ-ын трансформаторын салбарыг (ПБВ ±2×2.5 %) улиралд нэг удаа гараар солих бөгөөд хэрэглэгчийн хүчдэлийн хазайлтыг хамгийн их ба хамгийн бага ачааллын горимд ±5 %-д байлгах нөхцөлөөр сонгоно (лекц 12-т дэлгэрэнгүй).", "h": "Түгээх сүлжээнд 6–10 кВ-ын трансформаторын салбарыг (ПБВ ±2×2.5 %) улиралд нэг удаа гараар солих бөгөөд хэрэглэгчийн хүчдэлийн хазайлтыг хамгийн их ба хамгийн бага ачааллын горимд ±5 %-д байлгах нөхцөлөөр сонгоно (лекц 12-т дэлгэрэнгүй)."}, {"t": "h", "l": 1, "s": "16. Трансформаторыг тогтсон горимын тооцоонд оруулах дараалал", "h": "<b>16. Трансформаторыг тогтсон горимын тооцоонд оруулах дараалал</b>"}, {"t": "p", "s": "1. Паспортын өгөгдлийг (хүснэгт 3.1 эсвэл үйлдвэрийн) бэлтгэх; гурван ороомогт бол (3.6)-аар цацрагийн uк-г олох.", "h": "1. Паспортын өгөгдлийг (хүснэгт 3.1 эсвэл үйлдвэрийн) бэлтгэх; гурван ороомогт бол (3.6)-аар цацрагийн u<sub>к</sub>-г олох."}, {"t": "p", "s": "2. Rт, Xт-ийг дээд хүчдэлд (3.1)-ээр тооцож, нэгжийн харьцангуй системд шилжүүлэх (лекц 4).", "h": "2. R<sub>т</sub>, X<sub>т</sub>-ийг дээд хүчдэлд (3.1)-ээр тооцож, нэгжийн харьцангуй системд шилжүүлэх (лекц 4)."}, {"t": "p", "s": "3. Соронзлох салааг ΔṠх тогтмол ачаалал болгох эсвэл Gт − jBт-ээр Y матрицын диагональд нэмэх.", "h": "3. Соронзлох салааг ΔṠ<sub>х</sub> тогтмол ачаалал болгох эсвэл G<sub>т</sub> − jB<sub>т</sub>-ээр Y матрицын диагональд нэмэх."}, {"t": "p", "s": "4. РПН-ий одоогийн салбараар k*-ийг (3.7)-оор тооцох.", "h": "4. РПН-ий одоогийн салбараар k*-ийг (3.7)-оор тооцох."}, {"t": "p", "s": "5. (3.8) 2×2 матрицыг Yматрицад нэмэх (лекц 7); фаз шилжүүлэгч бол (3.12).", "h": "5. (3.8) 2×2 матрицыг Yматрицад нэмэх (лекц 7); фаз шилжүүлэгч бол (3.12)."}, {"t": "p", "s": "6. Тооцооны дараа нам талын хүчдэлийг шалгаж, шаардлагатай бол салбарыг өөрчилж дахин тооцох (лекц 12).", "h": "6. Тооцооны дараа нам талын хүчдэлийг шалгаж, шаардлагатай бол салбарыг өөрчилж дахин тооцох (лекц 12)."}, {"t": "h", "l": 1, "s": "17. Лабораторийн стендтэй холбоо", "h": "<b>17. Лабораторийн стендтэй холбоо</b>"}, {"t": "p", "s": "Стенд дээр шалгах (лекц 3, даалгавар 6). «Жишээ схем → 14 зангилаа»-г ачаал. Салбар 4–7, 4–9, 5–6 нь трансформатор (k ≠ 1). (1) 5–6 салааны k-г 0.932-оос 0.90 ба 1.00 болгож тус бүр F7-оор бод. (2) Зангилаа 5, 6-ын хүчдэл, зангилаа 6-ын генераторын Q, салааны идэвхгүй урсгалын өөрчлөлтийг хүснэгтэл. (3) «2. Y матриц» хуудаснаас Y55, Y56, Y66-ийн өөрчлөлтийг (3.8) томьёотой тулга. Дүгнэлт: k-г өөрчлөхөд бодит урсгал бараг өөрчлөгдөхгүй, идэвхгүй урсгал ба хүчдэл өөрчлөгдөнө — яагаад?", "h": "<b>Стенд дээр шалгах (лекц 3, даалгавар 6). </b>«Жишээ схем → 14 зангилаа»-г ачаал. Салбар 4–7, 4–9, 5–6 нь трансформатор (k ≠ 1). (1) 5–6 салааны k-г 0.932-оос 0.90 ба 1.00 болгож тус бүр F7-оор бод. (2) Зангилаа 5, 6-ын хүчдэл, зангилаа 6-ын генераторын Q, салааны идэвхгүй урсгалын өөрчлөлтийг хүснэгтэл. (3) «2. Y матриц» хуудаснаас Y<sub>55</sub>, Y<sub>56</sub>, Y<sub>66</sub>-ийн өөрчлөлтийг (3.8) томьёотой тулга. Дүгнэлт: k-г өөрчлөхөд бодит урсгал бараг өөрчлөгдөхгүй, идэвхгүй урсгал ба хүчдэл өөрчлөгдөнө — яагаад?"}, {"t": "h", "l": 1, "s": "Дүгнэлт", "h": "<b>Дүгнэлт</b>"}, {"t": "p", "s": "Трансформаторыг Г хэлбэрийн схемээр — цуваа Rт + jXт, хөндлөн Gт − jBт-ээр төлөөлнө; параметрийг ΔPк, uк%, ΔPх, Iх%-аас тооцно.", "h": "Трансформаторыг Г хэлбэрийн схемээр — цуваа R<sub>т</sub> + jX<sub>т</sub>, хөндлөн G<sub>т</sub> − jB<sub>т</sub>-ээр төлөөлнө; параметрийг ΔP<sub>к</sub>, u<sub>к</sub>%, ΔP<sub>х</sub>, I<sub>х</sub>%-аас тооцно."}, {"t": "p", "s": "Алдагдал тогтмол (ΔPх) ба хувьсах (ΔPкβ²) хэсэгтэй; трансформатор идэвхгүй чадлын томоохон хэрэглэгч.", "h": "Алдагдал тогтмол (ΔP<sub>х</sub>) ба хувьсах (ΔP<sub>к</sub>β²) хэсэгтэй; трансформатор идэвхгүй чадлын томоохон хэрэглэгч."}, {"t": "p", "s": "Гурван ороомогт трансформатор, автотрансформаторыг од схемээр, цацрагийн uк-г (3.6)-аар олно.", "h": "Гурван ороомогт трансформатор, автотрансформаторыг од схемээр, цацрагийн u<sub>к</sub>-г (3.6)-аар олно."}, {"t": "p", "s": "Нэрлэсэн бус коэффициентыг хамгийн тохиромжтой трансформатортой П схем — 2×2 матриц (3.8)-аар оруулна.", "h": "Нэрлэсэн бус коэффициентыг хамгийн тохиромжтой трансформатортой П схем — 2×2 матриц (3.8)-аар оруулна."}, {"t": "p", "s": "РПН-ийн салбар, зэрэгцээ ажиллагааны нөхцөл, оновчтой тоо нь хүчдэл ба алдагдлын горимд нөлөөлнө.", "h": "РПН-ийн салбар, зэрэгцээ ажиллагааны нөхцөл, оновчтой тоо нь хүчдэл ба алдагдлын горимд нөлөөлнө."}, {"t": "h", "l": 1, "s": "Хяналтын асуулт", "h": "<b>Хяналтын асуулт</b>"}, {"t": "p", "s": "1. Хоосон явалт ба богино залгааны туршилтаар юу тодорхойлдог вэ?", "h": "1. Хоосон явалт ба богино залгааны туршилтаар юу тодорхойлдог вэ?"}, {"t": "p", "s": "2. Rт, Xт, Gт, Bт-ийн томьёог бич.", "h": "2. R<sub>т</sub>, X<sub>т</sub>, G<sub>т</sub>, B<sub>т</sub>-ийн томьёог бич."}, {"t": "p", "s": "3. Трансформаторын хөндлөн дамжууламжийн тэмдэг шугамынхаас яагаад өөр вэ?", "h": "3. Трансформаторын хөндлөн дамжууламжийн тэмдэг шугамынхаас яагаад өөр вэ?"}, {"t": "p", "s": "4. Тогтмол ба хувьсах алдагдал; ашигт үйлийн хамгийн их утгын нөхцөл.", "h": "4. Тогтмол ба хувьсах алдагдал; ашигт үйлийн хамгийн их утгын нөхцөл."}, {"t": "p", "s": "5. Гурван ороомогт трансформаторын цацрагийн uк-г гарга. Яагаад сөрөг гарч болох вэ?", "h": "5. Гурван ороомогт трансформаторын цацрагийн u<sub>к</sub>-г гарга. Яагаад сөрөг гарч болох вэ?"}, {"t": "p", "s": "6. Автотрансформаторын хэрэглэх коэффициент, төрөл чадал.", "h": "6. Автотрансформаторын хэрэглэх коэффициент, төрөл чадал."}, {"t": "p", "s": "7. РПН ба ПБВ-ийн ялгаа; салбарын хүчдэлийг тооцох.", "h": "7. РПН ба ПБВ-ийн ялгаа; салбарын хүчдэлийг тооцох."}, {"t": "p", "s": "8. Хамгийн тохиромжтой трансформатортой П схемийн 2×2 матрицыг гарга.", "h": "8. Хамгийн тохиромжтой трансформатортой П схемийн 2×2 матрицыг гарга."}, {"t": "p", "s": "9. Зэрэгцээ ажиллах нөхцөл, тэгшитгэх гүйдэл.", "h": "9. Зэрэгцээ ажиллах нөхцөл, тэгшитгэх гүйдэл."}, {"t": "p", "s": "10. ТДН-10000/110-ын Rт, Xт, 8 + j6 МВА ачааллын үеийн алдагдлыг тооцоол.", "h": "10. ТДН-10000/110-ын R<sub>т</sub>, X<sub>т</sub>, 8 + j6 МВА ачааллын үеийн алдагдлыг тооцоол."}, {"t": "h", "l": 1, "s": "Бие даалтын даалгавар", "h": "<b>Бие даалтын даалгавар</b>"}, {"t": "p", "s": "Өөрийн вариантын (жагсаалтын дугаар N) өгөгдлөөр дараах тооцоог хийж, тайланг матриц хэлбэрийн бодолттойгоор бэлтгэнэ.", "h": "Өөрийн вариантын (жагсаалтын дугаар N) өгөгдлөөр дараах тооцоог хийж, тайланг матриц хэлбэрийн бодолттойгоор бэлтгэнэ."}, {"t": "p", "s": "1. ТДН-(10 000 + 1000N)/110 трансформаторын параметрийг хүснэгт 3.1-ийн ТДН-16000-ийн хувийн утгаар (uк = 10.5 %, ΔPк/Sн = 0.53 %, ΔPх/Sн = 0.12 %, Iх = 0.7 %) тооцоол.", "h": "1. ТДН-(10 000 + 1000N)/110 трансформаторын параметрийг хүснэгт 3.1-ийн ТДН-16000-ийн хувийн утгаар (u<sub>к</sub> = 10.5 %, ΔP<sub>к</sub>/S<sub>н</sub> = 0.53 %, ΔP<sub>х</sub>/S<sub>н</sub> = 0.12 %, I<sub>х</sub> = 0.7 %) тооцоол."}, {"t": "p", "s": "2. Нам талд 0.8·Sн ачаалал (cos φ = 0.85) байх үеийн алдагдал, хүчдэлийн уналтыг ол.", "h": "2. Нам талд 0.8·S<sub>н</sub> ачаалал (cos φ = 0.85) байх үеийн алдагдал, хүчдэлийн уналтыг ол."}, {"t": "p", "s": "3. РПН-ийн салбарыг нам талын хүчдэл 10.5 кВ байхаар сонго.", "h": "3. РПН-ийн салбарыг нам талын хүчдэл 10.5 кВ байхаар сонго."}, {"t": "p", "s": "4. Сонгосон салбарын k*-ээр трансформаторын 2×2 Yматрицыг (3.8) о.н.-д бич.", "h": "4. Сонгосон салбарын k*-ээр трансформаторын 2×2 Yматрицыг (3.8) о.н.-д бич."}, {"t": "p", "s": "5. Лекц 2-ын 110 кВ шугамтай гинжин хэлхээний ABCD матрицыг үржүүлж, эхлэлийн хүчдэлийг ол.", "h": "5. Лекц 2-ын 110 кВ шугамтай гинжин хэлхээний ABCD матрицыг үржүүлж, эхлэлийн хүчдэлийг ол."}, {"t": "p", "s": "6. Үр дүнг лабораторийн стенд дээр 2 зангилааны схем үүсгэж шалга.", "h": "6. Үр дүнг лабораторийн стенд дээр 2 зангилааны схем үүсгэж шалга."}, {"t": "h", "l": 1, "s": "Ашигласан ном", "h": "<b>Ашигласан ном</b>"}, {"t": "p", "s": "1. Ш.Гантөмөр. Цахилгаан станц, дэд станц: Сурах бичиг, I дэвтэр. 2-р хэвлэл. — УБ.: Соёмбопринтинг, 2014.", "h": "1. Ш.Гантөмөр. Цахилгаан станц, дэд станц: Сурах бичиг, I дэвтэр. 2-р хэвлэл. — УБ.: Соёмбопринтинг, 2014."}, {"t": "p", "s": "2. Ш.Гантөмөр. Цахилгаан шугам сүлжээ, систем. — УБ.: Соёмбопринтинг, 2017.", "h": "2. Ш.Гантөмөр. Цахилгаан шугам сүлжээ, систем. — УБ.: Соёмбопринтинг, 2017."}, {"t": "p", "s": "3. Ш.Гантөмөр. Цахилгаан системийн тогтсон горимын тооцооны математик загвар, аргачлал, алгоритм боловсруулах: Докторын ажил. — УБ.: МУШУТИС, 2005.", "h": "3. Ш.Гантөмөр. Цахилгаан системийн тогтсон горимын тооцооны математик загвар, аргачлал, алгоритм боловсруулах: Докторын ажил. — УБ.: МУШУТИС, 2005."}, {"t": "p", "s": "4. Grainger J.J., Stevenson W.D. Power SystemAnalysis. Ch. 2. — McGraw-Hill, 1994.", "h": "4. Grainger J.J., Stevenson W.D. Power SystemAnalysis. Ch. 2. — McGraw-Hill, 1994."}];